/// An event from the engine with its typed data. Unknown names (a newer engine) arrive as `.unknown`.
public enum EngineEvent: Sendable {
    case engineReady(EngineReadyEvent)
    case gateChanged(GateChangedEvent)
    case syncStatus(SyncStatusValue)
    case placeChanged(PlaceChangedEvent)
    case toast(ToastEvent)
    case navigateRequest(NavigateRequestEvent)
    case noteReady(NoteReadyEvent)
    case noteMeta(NoteMeta)
    case editorState(EditorStateEvent)
    case editorPanel(EditorPanelEvent)
    case memoryRelieved(MemoryRelievedEvent)
    case unknown(name: String, data: JSONValue)

    public var name: String {
        switch self {
        case .engineReady: "engine.ready"
        case .gateChanged: "gate.changed"
        case .syncStatus: "sync.status"
        case .placeChanged: "place.changed"
        case .toast: "toast"
        case .navigateRequest: "navigate.request"
        case .noteReady: "note.ready"
        case .noteMeta: "note.meta"
        case .editorState: "editor.state"
        case .editorPanel: "editor.panel"
        case .memoryRelieved: "memory.relieved"
        case .unknown(let name, _): name
        }
    }

    /// Decodes the `data` of an event named `name` from the envelope's container.
    static func decode<K: CodingKey>(name: String, from c: KeyedDecodingContainer<K>, key: K) throws -> EngineEvent {
        switch name {
        case "engine.ready": .engineReady(try c.decode(FoleviEngine.EngineReadyEvent.self, forKey: key))
        case "gate.changed": .gateChanged(try c.decode(FoleviEngine.GateChangedEvent.self, forKey: key))
        case "sync.status": .syncStatus(try c.decode(FoleviEngine.SyncStatusValue.self, forKey: key))
        case "place.changed": .placeChanged(try c.decode(FoleviEngine.PlaceChangedEvent.self, forKey: key))
        case "toast": .toast(try c.decode(FoleviEngine.ToastEvent.self, forKey: key))
        case "navigate.request": .navigateRequest(try c.decode(FoleviEngine.NavigateRequestEvent.self, forKey: key))
        case "note.ready": .noteReady(try c.decode(FoleviEngine.NoteReadyEvent.self, forKey: key))
        case "note.meta": .noteMeta(try c.decode(FoleviEngine.NoteMeta.self, forKey: key))
        case "editor.state": .editorState(try c.decode(FoleviEngine.EditorStateEvent.self, forKey: key))
        case "editor.panel": .editorPanel(try c.decode(FoleviEngine.EditorPanelEvent.self, forKey: key))
        case "memory.relieved": .memoryRelieved(try c.decode(FoleviEngine.MemoryRelievedEvent.self, forKey: key))
        default: .unknown(name: name, data: try c.decodeIfPresent(JSONValue.self, forKey: key) ?? .null)
        }
    }
}
